/** AudioWorklet processor that runs the WASM DSP core block by block. */
import { EVENT_FIELDS, INBOX_EVENTS, PROCESSOR_NAME, type FromProcessor, type ProcessorSetup, type ToProcessor } from "./protocol.ts";

const BLOCK_FRAMES = 128;

interface DspExports {
  readonly memory: WebAssembly.Memory;
  programBuffer(length: number): number;
  loadPatch(rate: number): void;
  inboxBuffer(): number;
  receiveEvents(count: number): void;
  recordingBuffer(): number;
  recordingRightBuffer(): number;
  render(blockStart: number): void;
  outputLeft(): number;
  outputRight(): number;
  droppedEvents(): number;
}

interface MemoryHolder {
  memory?: WebAssembly.Memory;
}

/** Reads an AssemblyScript string: UTF-16 after a byte length. */
function readText(holder: MemoryHolder, pointer: number): string {
  if (!holder.memory || pointer === 0) return "";
  const byteLength = new Uint32Array(holder.memory.buffer, pointer - 4, 1)[0];
  return String.fromCharCode(...new Uint16Array(holder.memory.buffer, pointer, byteLength >>> 1));
}

function instantiate(bytes: ArrayBuffer): DspExports {
  const holder: MemoryHolder = {};
  const abort = (message: number, file: number, line: number, column: number) => {
    throw new Error(`DSP core: ${readText(holder, message)} at ${readText(holder, file)}:${line}:${column}`);
  };
  const instance = new WebAssembly.Instance(new WebAssembly.Module(bytes), { env: { abort } });
  const exports = instance.exports as unknown as DspExports;
  holder.memory = exports.memory;
  return exports;
}

/** Collects rendered frames into chunks and posts each one when full. */
class ChunkCapture {
  private readonly chunkFrames: number;
  private readonly totalFrames: number;
  private captured = 0;
  private index = 0;
  private filled = 0;
  private left: Float32Array;
  private right: Float32Array;

  constructor(chunkFrames: number, totalFrames: number) {
    this.chunkFrames = chunkFrames;
    this.totalFrames = totalFrames;
    this.left = new Float32Array(Math.min(chunkFrames, totalFrames));
    this.right = new Float32Array(this.left.length);
  }

  /** Copies one block in; posts the chunk once it is full. */
  take(left: Float32Array, right: Float32Array, port: MessagePort): void {
    const count = Math.min(BLOCK_FRAMES, this.left.length - this.filled, this.totalFrames - this.captured);
    if (count <= 0) return;
    this.left.set(left.subarray(0, count), this.filled);
    this.right.set(right.subarray(0, count), this.filled);
    this.filled += count;
    this.captured += count;
    if (this.filled < this.left.length) return;
    const message: FromProcessor = { type: "chunk", index: this.index, left: this.left, right: this.right };
    port.postMessage(message, [this.left.buffer, this.right.buffer]);
    this.index += 1;
    this.filled = 0;
    const remaining = Math.min(this.chunkFrames, this.totalFrames - this.captured);
    this.left = new Float32Array(Math.max(remaining, 0));
    this.right = new Float32Array(this.left.length);
  }
}

/** Runs the DSP core; one instance per engine context. */
class DspProcessor extends AudioWorkletProcessor {
  private readonly dsp: DspExports;
  private leftView: Float32Array;
  private rightView: Float32Array;
  private capture: ChunkCapture | null = null;
  private running = true;

  constructor(options: AudioWorkletNodeOptions) {
    super(options);
    const setup = options.processorOptions as ProcessorSetup;
    this.dsp = instantiate(setup.wasmBytes);
    const address = this.dsp.programBuffer(setup.program.length);
    new Float64Array(this.dsp.memory.buffer, address, setup.program.length).set(setup.program);
    this.dsp.loadPatch(sampleRate);
    this.leftView = new Float32Array(this.dsp.memory.buffer, this.dsp.outputLeft(), BLOCK_FRAMES);
    this.rightView = new Float32Array(this.dsp.memory.buffer, this.dsp.outputRight(), BLOCK_FRAMES);
    this.port.onmessage = (event: MessageEvent<ToProcessor>) => this.receiveSafely(event.data);
  }

  private receiveSafely(message: ToProcessor): void {
    try {
      this.receive(message);
    } catch (failure) {
      const reply: FromProcessor = { type: "error", message: String((failure as Error).message ?? failure) };
      this.port.postMessage(reply);
      throw failure;
    }
  }

  private receive(message: ToProcessor): void {
    if (message.type === "events") this.receiveEvents(message.records);
    else if (message.type === "recording") this.receiveRecording(message.instrumentIndex, message.midi, message.rate, message.channels);
    else if (message.type === "capture") this.capture = new ChunkCapture(message.chunkFrames, message.totalFrames);
    else if (message.type === "stop") this.running = false;
    else this.port.postMessage({ type: "synced", id: message.id } satisfies FromProcessor);
  }

  private receiveEvents(records: Float64Array): void {
    const batch = INBOX_EVENTS * EVENT_FIELDS;
    for (let start = 0; start < records.length; start += batch) {
      const slice = records.subarray(start, Math.min(start + batch, records.length));
      new Float64Array(this.dsp.memory.buffer, this.dsp.inboxBuffer(), slice.length).set(slice);
      this.dsp.receiveEvents(slice.length / EVENT_FIELDS);
    }
    const dropped = this.dsp.droppedEvents();
    if (dropped > 0) throw new Error(`DSP event queue overflowed; ${dropped} events dropped`);
  }

  private receiveRecording(instrumentIndex: number, midi: number, rate: number, channels: Float32Array[]): void {
    const frames = channels[0].length;
    new Float64Array(this.dsp.memory.buffer, this.dsp.inboxBuffer(), 5).set([instrumentIndex, midi, frames, channels.length, rate]);
    const leftAddress = this.dsp.recordingBuffer();
    new Float32Array(this.dsp.memory.buffer, leftAddress, frames).set(channels[0]);
    if (channels.length > 1) new Float32Array(this.dsp.memory.buffer, this.dsp.recordingRightBuffer(), frames).set(channels[1]);
  }

  process(_inputs: Float32Array[][], outputs: Float32Array[][]): boolean {
    if (!this.running) return false;
    this.dsp.render(currentFrame);
    if (this.leftView.byteLength === 0) this.refreshViews();
    const output = outputs[0];
    output[0]?.set(this.leftView);
    output[1]?.set(this.rightView);
    this.capture?.take(this.leftView, this.rightView, this.port);
    return true;
  }

  private refreshViews(): void {
    this.leftView = new Float32Array(this.dsp.memory.buffer, this.dsp.outputLeft(), BLOCK_FRAMES);
    this.rightView = new Float32Array(this.dsp.memory.buffer, this.dsp.outputRight(), BLOCK_FRAMES);
  }
}

registerProcessor(PROCESSOR_NAME, DspProcessor);
